package com.baraka.game.cratecrew.model

/**
 * One Crate Crew puzzle. [layout] rows use: '#' wall, '.' floor, 'T' target, 'C' crate,
 * 'B' crate already on a target, 'P' player, 'S' player standing on a target, ' ' outside
 * the room. Rows need not be the same length; short rows are padded with spaces.
 *
 * Every level here is generated by pulling crates away from a solved state and verified with
 * a breadth-first solver, so a solution of [par] moves or fewer always exists.
 */
data class CrateLevel(
    val name: String,
    val layout: List<String>,
    val par: Int
)

